import plotly.graph_objects as go
import pandas as pd
years = ['1952', '1962', '1967', '1972', '1977', '1982', '1987', '1992', '1997', '2002', '2007']
continents = []
for continent in df['continent']:
    if continent not in continents:
        continents.append(continent)
fig_dict = {'data': [], 'layout': {}, 'frames': []}
fig_dict['layout']['xaxis'] = {'range': [30, 85], 'title': 'Life Expectancy'}
fig_dict['layout']['yaxis'] = {'title': 'GDP per Capita', 'type': 'log'}
fig_dict['layout']['hovermode'] = 'closest'
fig_dict['layout']['updatemenus'] = [{'buttons': [{'args': [None, {'frame': {'duration': 500, 'redraw': False}, 'fromcurrent': True, 'transition': {'duration': 300, 'easing': 'quadratic-in-out'}}], 'label': 'Play', 'method': 'animate'}, {'args': [[None], {'frame': {'duration': 0, 'redraw': False}, 'mode': 'immediate', 'transition': {'duration': 0}}], 'label': 'Pause', 'method': 'animate'}], 'direction': 'left', 'pad': {'r': 10, 't': 87}, 'showactive': False, 'type': 'buttons', 'x': 0.1, 'xanchor': 'right', 'y': 0, 'yanchor': 'top'}]
sliders_dict = {'active': 0, 'yanchor': 'top', 'xanchor': 'left', 'currentvalue': {'font': {'size': 20}, 'prefix': 'Year:', 'visible': True, 'xanchor': 'right'}, 'transition': {'duration': 300, 'easing': 'cubic-in-out'}, 'pad': {'b': 10, 't': 50}, 'len': 0.9, 'x': 0.1, 'y': 0, 'steps': []}
for year in years:
    frame = {'data': [], 'name': str(year)}
    for continent in continents:
        dataset_by_year = df[df['year'] == int(year)]
        dataset_by_year_and_cont = dataset_by_year[dataset_by_year['continent'] == continent]
        data_dict = {'x': list(dataset_by_year_and_cont['lifeExp']), 'y': list(dataset_by_year_and_cont['gdpPercap']), 'mode': 'markers', 'text': list(dataset_by_year_and_cont['country']), 'marker': {'sizemode': 'area', 'sizeref': 200000, 'size': list(dataset_by_year_and_cont['pop'])}, 'name': continent}
        frame['data'].append(data_dict)
    fig_dict['frames'].append(frame)
    slider_step = {'args': [[year], {'frame': {'duration': 300, 'redraw': False}, 'mode': 'immediate', 'transition': {'duration': 300}}], 'label': year, 'method': 'animate'}
    sliders_dict['steps'].append(slider_step)
fig_dict['layout']['sliders'] = [sliders_dict]
fig_dict['data'] = fig_dict['frames'][0]['data']
fig = go.Figure(fig_dict)
print(fig.to_json())

import plotly.graph_objects as go
import pandas as pd
df.rename(columns={'Unnamed: 0': 'Category'}, inplace=True)
for v in ['Disagree', 'Strongly Disagree']:
    df[v] = df[v] * -1
fig = go.Figure()
color_by_category = {'Strongly Agree': 'darkblue', 'Agree': 'lightblue', 'Disagree': 'orange', 'Strongly Disagree': 'red'}
legend_rank_by_category = {'Strongly Disagree': 1, 'Disagree': 2, 'Agree': 3, 'Strongly Agree': 4}
for col in ['Disagree', 'Strongly Disagree', 'Agree', 'Strongly Agree']:
    fig.add_trace(go.Bar(y=df['Category'], x=df[col], name=col, orientation='h', marker=dict(color=color_by_category[col]), legendrank=legend_rank_by_category[col]))
fig.update_layout(title='Reactions to statements from the 2002 General Social Survey:', yaxis_title='', barmode='relative', plot_bgcolor='white')
fig.update_xaxes(title='Percent of Responses', zeroline=True, zerolinecolor='black', tickmode='array', tickvals=[-50, 0, 50, 100], ticktext=[50, 0, 50, 100])
print(fig.to_json())
